import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import '../../core/routes/app_routes.dart';import '../../core/utils/formatters.dart';import '../../models/invoice.dart';import '../../services/invoice_service.dart';import '../../widgets/empty_state.dart';import '../../widgets/error_state.dart';
class InvoicesScreen extends StatefulWidget {final InvoiceService service;const InvoicesScreen({super.key,required this.service});@override State<InvoicesScreen> createState()=>_InvoicesScreenState();}
class _InvoicesScreenState extends State<InvoicesScreen> {late Future<List<Invoice>> future;@override void initState(){super.initState();reload();}void reload(){setState(()=>future=widget.service.list());}
 Future<void> remove(Invoice invoice)async{final confirmed=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Excluir nota?'),content:Text('NF ${invoice.number}'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancelar')),TextButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Excluir'))]));if(confirmed!=true)return;try{await widget.service.delete(invoice.id!);reload();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('LANÇAMENTO DE NOTAS'),leading:IconButton(icon:const Icon(Icons.home),onPressed:()=>context.go(AppRoutes.home))),floatingActionButton:FloatingActionButton.extended(onPressed:()=>context.go(AppRoutes.invoiceNew),icon:const Icon(Icons.add),label:const Text('Nova nota')),body:FutureBuilder<List<Invoice>>(future:future,builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return ErrorState(message:'${s.error}',onRetry:reload);final invoices=s.data??[];if(invoices.isEmpty)return const EmptyState(message:'Nenhuma nota cadastrada.');return RefreshIndicator(onRefresh:()async{reload();await future;},child:ListView.builder(itemCount:invoices.length,itemBuilder:(context,i){final x=invoices[i];return Card(child:ListTile(title:Text('NF ${x.number} — ${x.supplier}'),subtitle:Text('${Formatters.date(x.issueDate)} · ${Formatters.money(x.grossTotal)}'),onTap:()=>context.go(AppRoutes.invoiceEdit(x.id!)),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>remove(x))));}));}));}
}
